FQuat4d FRotator3d::Quaternion() const
{
	DiagnosticCheckNaN();

#if PLATFORM_ENABLE_VECTORINTRINSICS
	const VectorRegister4Double Angles = MakeVectorRegisterDouble(Pitch, Yaw, Roll, 0.0);
	const VectorRegister4Double AnglesNoWinding = VectorMod360(Angles);
	const VectorRegister4Double HalfAngles = VectorMultiply(AnglesNoWinding, GlobalVectorConstants::DOUBLE_DEG_TO_RAD_HALF);

	VectorRegister4Double SinAngles, CosAngles;
	VectorSinCos(&SinAngles, &CosAngles, &HalfAngles);

	// Vectorized conversion, measured 20% faster than using scalar version after VectorSinCos.
	// Indices within VectorRegister (for shuffles): P=0, Y=1, R=2
	const VectorRegister4Double SR = VectorReplicate(SinAngles, 2);
	const VectorRegister4Double CR = VectorReplicate(CosAngles, 2);

	const VectorRegister4Double SY_SY_CY_CY_Temp = VectorShuffle(SinAngles, CosAngles, 1, 1, 1, 1);

	const VectorRegister4Double SP_SP_CP_CP = VectorShuffle(SinAngles, CosAngles, 0, 0, 0, 0);
	const VectorRegister4Double SY_CY_SY_CY = VectorShuffle(SY_SY_CY_CY_Temp, SY_SY_CY_CY_Temp, 0, 2, 0, 2);

	const VectorRegister4Double CP_CP_SP_SP = VectorShuffle(CosAngles, SinAngles, 0, 0, 0, 0);
	const VectorRegister4Double CY_SY_CY_SY = VectorShuffle(SY_SY_CY_CY_Temp, SY_SY_CY_CY_Temp, 2, 0, 2, 0);

	const uint64 Neg = uint64(1) << 63;
	const uint64 Pos = uint64(0);
	const VectorRegister4Double SignBitsLeft = MakeVectorRegisterDoubleMask(Pos, Neg, Pos, Pos);
	const VectorRegister4Double SignBitsRight = MakeVectorRegisterDoubleMask(Neg, Neg, Neg, Pos);
	const VectorRegister4Double LeftTerm = VectorBitwiseXor(SignBitsLeft, VectorMultiply(CR, VectorMultiply(SP_SP_CP_CP, SY_CY_SY_CY)));
	const VectorRegister4Double RightTerm = VectorBitwiseXor(SignBitsRight, VectorMultiply(SR, VectorMultiply(CP_CP_SP_SP, CY_SY_CY_SY)));

	const VectorRegister4Double Result = VectorAdd(LeftTerm, RightTerm);

FORCEINLINE VectorRegister4Float VectorNegateMultiplyAdd(VectorRegister4Float Vec1, VectorRegister4Float Vec2, VectorRegister4Float Sub)
{
	return vfmsq_f32(Sub, Vec1, Vec2);
}

FORCEINLINE VectorRegister4Double VectorNegateMultiplyAdd(VectorRegister4Double Vec1, VectorRegister4Double Vec2, VectorRegister4Double Sub)
{
	VectorRegister4Double Result;
	Result.XY = vfmsq_f64(Sub.XY, Vec1.XY, Vec2.XY);
	Result.ZW = vfmsq_f64(Sub.ZW, Vec1.ZW, Vec2.ZW);
	return Result;

FORCEINLINE VectorRegister4Double VectorSin(VectorRegister4Double X)
{
	AlignedDouble4 Doubles(X);
	Doubles[0] = FMath::Sin(Doubles[0]);
	Doubles[1] = FMath::Sin(Doubles[1]);
	Doubles[2] = FMath::Sin(Doubles[2]);
	Doubles[3] = FMath::Sin(Doubles[3]);
	return Doubles.ToVectorRegister();
}

FORCEINLINE VectorRegister4Float VectorCos(VectorRegister4Float X)
{
	return VectorSin(VectorAdd(X, GlobalVectorConstants::PiByTwo));
}

FORCEINLINE VectorRegister4Double VectorCos(VectorRegister4Double X)
{
	AlignedDouble4 Doubles(X);
	Doubles[0] = FMath::Cos(Doubles[0]);
	Doubles[1] = FMath::Cos(Doubles[1]);
	Doubles[2] = FMath::Cos(Doubles[2]);
	Doubles[3] = FMath::Cos(Doubles[3]);
	return Doubles.ToVectorRegister();
}

FORCEINLINE void VectorSinCos(VectorRegister4Double* RESTRICT VSinAngles, VectorRegister4Double* RESTRICT VCosAngles, const VectorRegister4Double* RESTRICT VAngles)
{
	*VSinAngles = VectorSin(*VAngles);
	*VCosAngles = VectorCos(*VAngles);
}

FORCEINLINE VectorRegister4Float VectorMod360(VectorRegister4Float X)
{
	// R = X - (Y * (Trunc(X / Y))
	VectorRegister4Float Temp = VectorTruncate(VectorDivide(X, GlobalVectorConstants::Float360));
	VectorRegister4Float FloatResult = VectorNegateMultiplyAdd(GlobalVectorConstants::Float360, Temp, X);
	return FloatResult;
}

FORCEINLINE VectorRegister4Double VectorMod360(VectorRegister4Double X)
{
	// R = X - (Y * (Trunc(X / Y))
	VectorRegister4Double Temp = VectorTruncate(VectorDivide(X, GlobalVectorConstants::Double360));
	VectorRegister4Double DoubleResult = VectorNegateMultiplyAdd(GlobalVectorConstants::Double360, Temp, X);
	return DoubleResult;

inline constexpr VectorRegister4Float DEG_TO_RAD_HALF = MakeVectorRegisterConstant((UE_PI/180.f)*0.5f, (UE_PI/180.f)*0.5f, (UE_PI/180.f)*0.5f, (UE_PI/180.f)*0.5f);
inline constexpr VectorRegister4Float RAD_TO_DEG = MakeVectorRegisterConstant((180.f)/UE_PI, (180.f)/UE_PI, (180.f)/UE_PI, (180.f)/UE_PI);
inline constexpr VectorRegister4Double DOUBLE_DEG_TO_RAD = MakeVectorRegisterConstant(UE_DOUBLE_PI/(180.), UE_DOUBLE_PI/(180.), UE_DOUBLE_PI/(180.), UE_DOUBLE_PI/(180.));
inline constexpr VectorRegister4Double DOUBLE_DEG_TO_RAD_HALF = MakeVectorRegisterConstant((UE_DOUBLE_PI/180.) * 0.5, (UE_DOUBLE_PI/180.) * 0.5, (UE_DOUBLE_PI/180.) * 0.5, (UE_DOUBLE_PI/180.) * 0.5);
inline constexpr VectorRegister4Double DOUBLE_RAD_TO_DEG = MakeVectorRegisterConstant((180.)/UE_DOUBLE_PI, (180.)/UE_DOUBLE_PI, (180.)/UE_DOUBLE_PI, (180.)/UE_DOUBLE_PI);

	if (!bInitialized)
	{
		bInitialized = true;

		OffsetNormal = FootOffsetNormal;

		// Get the foot initial rotation and convert it to the calf space.

		const auto CalfInitialRotation{Hierarchy->GetInitialGlobalTransform(CachedCalfItem).GetRotation()};
		const auto FootInitialRotation{Hierarchy->GetInitialGlobalTransform(CachedFootItem).GetRotation()};

		FootInitialRotationCalfSpace = CalfInitialRotation.Inverse() * FootInitialRotation;
	}

	OffsetNormal = UAlsMath::DamperExact(OffsetNormal, FootOffsetNormal,
	                                     UE_REAL_TO_FLOAT(ExecuteContext.GetDeltaTime()), OffsetInterpolationHalfLife);

	const auto OffsetRotation{FQuat::FindBetweenVectors(FVector::UpVector, OffsetNormal)};

	// Transform the current foot rotation and the target foot rotation with applied foot offset to the calf space.

	const auto CalfRotation{Hierarchy->GetGlobalTransform(CachedCalfItem).GetRotation()};
	FootRotation = Hierarchy->GetGlobalTransform(CachedFootItem).GetRotation();

	const auto CurrentRotationCalfSpace{
		(CalfRotation.Inverse() * FootRotation * FootInitialRotationCalfSpace.Inverse()).Rotator()
	};

	const auto TargetRotationCalfSpace{
		(CalfRotation.Inverse() * (OffsetRotation * FootTargetRotation) * FootInitialRotationCalfSpace.Inverse()).Rotator()
	};

	// Apply limits.

	static const auto ConstraintTargetAngle{
		[](const float CurrentAngle, const float TargetAngle, const FFloatInterval& LimitAngle)
		{
			// Initial rotation is the rotation of the foot that comes from animations. It must be taken
			// into account so that, for example, if the foot is rotated 45 degrees in the animation
			// and the limit angle is 25 degrees, the resulting foot rotation will still be 45 degrees.

			const auto MinAngle{FMath::Min3(CurrentAngle, LimitAngle.Min, LimitAngle.Max)};
			const auto MaxAngle{FMath::Max3(CurrentAngle, LimitAngle.Min, LimitAngle.Max)};

			return FMath::Clamp(TargetAngle, MinAngle, MaxAngle);
		}
	};

	const auto FinalPitchAngleCalfSpace{
		ConstraintTargetAngle(UE_REAL_TO_FLOAT(CurrentRotationCalfSpace.Pitch),
		                      UE_REAL_TO_FLOAT(TargetRotationCalfSpace.Pitch),
		                      Swing2LimitAngle)
	};

	const auto FinalYawAngleCalfSpace{
		ConstraintTargetAngle(UE_REAL_TO_FLOAT(CurrentRotationCalfSpace.Yaw),
		                      UE_REAL_TO_FLOAT(TargetRotationCalfSpace.Yaw),
		                      Swing1LimitAngle)
	};

	const auto FinalRollAngleCalfSpace{
		ConstraintTargetAngle(UE_REAL_TO_FLOAT(CurrentRotationCalfSpace.Roll),
		                      UE_REAL_TO_FLOAT(TargetRotationCalfSpace.Roll),
		                      TwistLimitAngle)
	};

	const auto FinalRotationCalfSpace{FRotator{FinalPitchAngleCalfSpace, FinalYawAngleCalfSpace, FinalRollAngleCalfSpace}.Quaternion()};

	// Convert the new calf space foot rotation back to the global space.

	FootRotation = CalfRotation * (FinalRotationCalfSpace * FootInitialRotationCalfSpace);
	FootRotation.Normalize();

use crate::als::animation::inv_exp_approx;
use bevy::{
    math::{DQuat, DVec3, EulerRot},
    prelude::Reflect,
};
use serde::{Deserialize, Serialize};

pub fn rig_damper_alpha(delta_seconds: f32, half_life: f32) -> f32 {
    1.0 - inv_exp_approx(std::f32::consts::LN_2 / (half_life + 1e-8) * delta_seconds)
}

pub fn rig_clamp01(value: f32) -> f32 {
    if value > 0.0 {
        if value < 1.0 { value } else { 1.0 }
    } else {
        0.0
    }
}

pub fn rig_quaternion(euler: DVec3) -> DQuat {
    DQuat::from_euler(
        EulerRot::YZX,
        (euler.y % 360.0).to_radians(),
        (euler.z % 360.0).to_radians(),
        (euler.x % 360.0).to_radians(),
    )
}

pub enum RigMathOp {
    F32Add,
    F32Mul,
    F32Min,
    F32Clamp01,
    F64Add,
    F64Sub,
    F64Mul,
    F64Abs,
    F64Clamp,
    F64Lerp,
    F64GreaterEqual,
    VectorAdd,
    VectorScale,
    QuaternionFromEulerYzx,
}

impl RigMathOp {
    pub fn evaluate(self, inputs: &[RigValue]) -> Result<RigValue, String> {
        use RigValue::*;
        Ok(match (self, inputs) {
            (Self::F32Add, [F32(a), F32(b)]) => F32(a + b),
            (Self::F32Mul, [F32(a), F32(b)]) => F32(a * b),
            (Self::F32Min, [F32(a), F32(b)]) => F32(if a < b { *a } else { *b }),
            (Self::F32Clamp01, [F32(value)]) => F32(rig_clamp01(*value)),
            (Self::F64Add, [F64(a), F64(b)]) => F64(a + b),
            (Self::F64Sub, [F64(a), F64(b)]) => F64(a - b),
            (Self::F64Mul, [F64(a), F64(b)]) => F64(a * b),
            (Self::F64Abs, [F64(value)]) => F64(value.abs()),
            (Self::F64Clamp, [F64(value), F64(minimum), F64(maximum)]) => {
                let upper = if value < maximum { *value } else { *maximum };
                F64(if *minimum < upper { upper } else { *minimum })
            }
            (Self::F64Lerp, [F64(a), F64(b), F64(t)]) => F64(a + t * (b - a)),
            (Self::F64GreaterEqual, [F64(a), F64(b)]) => Bool(a >= b),
            (Self::VectorAdd, [Vector(a), Vector(b)]) => Vector(*a + *b),
            (Self::VectorScale, [Vector(value), F32(factor)]) => Vector(*value * *factor as f64),
            (Self::QuaternionFromEulerYzx, [EulerDegrees(value)]) => {
                Quaternion(rig_quaternion(*value))
            }
            _ => {

    "FAlsRigUnit_ApplyFootOffsetRotation::Execute",
    [
        calf,
        foot,
        Quaternion(target),
        Vector(normal),
        List(swing_y),
        List(swing_z),
        List(twist_x),
        F32(half_life),
        Bool(initialized),
        _cached_calf,
        _cached_foot,
        Vector(offset_normal),
        Quaternion(rotation),
        Quaternion(initial_rotation),
    ],
) => {
    let Some(calf) = self.hierarchy.item_index(calf)? else {
        return Ok(());
    };
    let Some(foot) = self.hierarchy.item_index(foot)? else {
        return Ok(());
    };
    if !*initialized {
        *initialized = true;
        *offset_normal = *normal;
        let calf = self
            .hierarchy
            .transform(calf, RigSpace::Global, true)?
            .rotation;
        let foot = self
            .hierarchy
            .transform(foot, RigSpace::Global, true)?
            .rotation;
        *initial_rotation = calf.conjugate() * foot;
    }
    *offset_normal += (*normal - *offset_normal)
        * rig_damper_alpha(self.delta_seconds as f32, *half_life) as f64;
    let offset_rotation = self
        .geometry
        .between_vectors(self.geometry.basis[2], *offset_normal);
    let calf = self
        .hierarchy
        .transform(calf, RigSpace::Global, false)?
        .rotation;
    let foot = self
        .hierarchy
        .transform(foot, RigSpace::Global, false)?
        .rotation;
    let current = rig_euler(calf.conjugate() * foot * initial_rotation.conjugate());
    let target = rig_euler(
        calf.conjugate() * (offset_rotation * *target) * initial_rotation.conjugate(),
    );
    let euler = DVec3::new(
        constrained_angle(current.x, target.x, twist_x)?,
        constrained_angle(current.y, target.y, swing_y)?,
        constrained_angle(current.z, target.z, swing_z)?,
    );
    *rotation = rig_normalize(calf * (rig_quaternion(euler) * *initial_rotation));
